    payload = AccountSwitchPayload.model_validate(body, strict=True)

    if payload.account_id not in current_user.allowed_account_ids:
        raise HTTPException(status_code=403, detail="Not authorized for this account")

    target_account = await account_mgr.get_account(payload.account_id)
    if not target_account:
        raise HTTPException(status_code=404, detail="Account not found")

    token = await account_mgr.generate_context_token(
        user_id=current_user.id,
        account_id=target_account.id
